const assert = require('node:assert/strict');

const { EventService } = require('../.build/service');

// Builds a Source conforming to the interface in src/source.ts and records
// every interaction (opens/reads/closes plus the raw operation order).
function scriptedSource(options = {}) {
  const values = [...(options.values ?? [])];
  const state = { opens: 0, reads: 0, closes: 0, ops: [] };
  const source = {
    open: async () => {
      state.opens++;
      state.ops.push('open');
      if (options.openError) throw options.openError;
      return {
        read: async () => {
          state.reads++;
          state.ops.push('read');
          if (options.readError) throw options.readError;
          const value = values.length > 0 ? values.shift() : null;
          return value;
        },
        close: async () => {
          state.closes++;
          state.ops.push('close');
          if (options.closeError) throw options.closeError;
        },
      };
    },
  };
  return { source, state };
}

async function lazyOpenAndNoEarlyClose() {
  const { source, state } = scriptedSource({ values: ['a', 'b'] });
  const service = new EventService(source);
  const iterator = service.stream();
  assert.equal(state.opens, 0, 'must not open before first next()');
  assert.equal((await iterator.next()).value, 'A');
  assert.equal(state.opens, 1, 'must open on first next()');
  assert.equal(state.reads, 1, 'exactly one read per next()');
  assert.equal(state.closes, 0, 'must not close while records are flowing');
  await iterator.return();
  assert.equal(state.closes, 1, 'return() closes the opened lease exactly once');
  assert.deepEqual(state.ops, ['open', 'read', 'close']);
}

async function returningUnopenedGeneratorIsInert() {
  const { source, state } = scriptedSource({ values: ['a'] });
  const service = new EventService(source);
  const iterator = service.stream();
  const result = await iterator.return();
  assert.equal(result.done, true);
  assert.equal(state.opens, 0, 'return() before first next() must not open');
  assert.equal(state.closes, 0, 'return() before first next() must not close');
  assert.deepEqual(state.ops, []);
}

async function normalExhaustionClosesOnce() {
  const { source, state } = scriptedSource({ values: ['a', 'b'] });
  const service = new EventService(source);
  const found = [];
  for await (const value of service.stream()) found.push(value);
  assert.deepEqual(found, ['A', 'B']);
  assert.deepEqual(state.ops, ['open', 'read', 'read', 'read', 'close'], 'one read per next(); the third read establishes exhaustion');
  assert.equal(state.closes, 1);
}

async function consumerBreakClosesOnceWithoutReadAhead() {
  const { source, state } = scriptedSource({ values: ['a', 'b', 'c'] });
  const service = new EventService(source);
  const found = [];
  for await (const value of service.stream()) {
    found.push(value);
    if (found.length === 1) break;
  }
  assert.deepEqual(found, ['A']);
  assert.deepEqual(state.ops, ['open', 'read', 'close'], 'break must not read ahead');
  assert.equal(state.closes, 1);
}

async function readFailureClosesAndPreservesReadError() {
  const readError = new Error('read boom');
  const closeError = new Error('close boom');
  const { source, state } = scriptedSource({ values: ['a'], readError, closeError });
  const service = new EventService(source);
  await assert.rejects(
    async () => {
      for await (const value of service.stream()) void value;
    },
    (error) => error === readError,
    'the original read error must win over a close failure',
  );
  assert.equal(state.closes, 1);
}

async function mapperFailureClosesAndPreservesMapperError() {
  const mapperError = new Error('mapper boom');
  const closeError = new Error('close boom');
  const { source, state } = scriptedSource({ values: ['a'], closeError });
  const service = new EventService(source, () => {
    throw mapperError;
  });
  await assert.rejects(
    async () => {
      for await (const value of service.stream()) void value;
    },
    (error) => error === mapperError,
    'the original mapper error must win over a close failure',
  );
  assert.equal(state.closes, 1);
  assert.deepEqual(state.ops, ['open', 'read', 'close']);
}

async function injectedThrowClosesAndPreservesInjectedError() {
  const injected = new Error('injected boom');
  const closeError = new Error('close boom');
  const { source, state } = scriptedSource({ values: ['a', 'b'], closeError });
  const service = new EventService(source);
  const iterator = service.stream();
  assert.equal((await iterator.next()).value, 'A');
  await assert.rejects(
    () => iterator.throw(injected),
    (error) => error === injected,
    'the injected error must win over a close failure',
  );
  assert.equal(state.closes, 1);
}

async function closeFailurePropagatesOnExhaustion() {
  const closeError = new Error('close boom');
  const { source, state } = scriptedSource({ values: ['a'], closeError });
  const service = new EventService(source);
  await assert.rejects(
    async () => {
      for await (const value of service.stream()) void value;
    },
    (error) => error === closeError,
    'with no competing exception, the close failure must propagate',
  );
  assert.equal(state.closes, 1);
  assert.deepEqual(state.ops, ['open', 'read', 'read', 'close']);
}

async function main() {
  await lazyOpenAndNoEarlyClose();
  await returningUnopenedGeneratorIsInert();
  await normalExhaustionClosesOnce();
  await consumerBreakClosesOnceWithoutReadAhead();
  await readFailureClosesAndPreservesReadError();
  await mapperFailureClosesAndPreservesMapperError();
  await injectedThrowClosesAndPreservesInjectedError();
  await closeFailurePropagatesOnExhaustion();
}

module.exports = main();
